namespace MystieHook.Games.Wardog;

// Read-only layouts established by complete independent live captures, including
// the nine-byte leaf from the user's held-AK v4 report. Never execute this code.
// Component wrapper and complete sparse lookup match the October 15/16 user
// captures exactly, including call operands. Never execute captured code.
public static class WardogPredictionSpeedLayout
{
    public const ulong GetterRva=WardogFunctionOffsets.InitialBulletSpeed, ComponentWrapperRva=WardogFunctionOffsets.GetComponentByClass;
    public const ulong ModifierOffset=0x114, InitialSpeedOffset=0x140+0xDA0;
    internal static readonly byte[] Getter=Convert.FromHexString("40534883EC30488B42204533C94885C00F29742420498BD8410F95C14C03C84C894A20F30F10B1140100004881C140010000E8F9480200F30F59C60F28742420F30F11034883C4305BC3");
    internal static readonly byte[] Helper=Convert.FromHexString("F30F1081A00D0000C3");
    internal static readonly byte[] ComponentWrapper=Convert.FromHexString("");
    internal static readonly byte[] ComponentLookup=Convert.FromHexString("");
    public static bool MatchesGetter(ReadOnlySpan<byte> code)=>code.SequenceEqual(Getter);
    public static bool MatchesHelper(ReadOnlySpan<byte> code)=>code.SequenceEqual(Helper);
    public static bool MatchesComponentWrapper(ReadOnlySpan<byte> code)=>code.SequenceEqual(ComponentWrapper);
    public static bool MatchesComponentLookup(ReadOnlySpan<byte> code)=>code.SequenceEqual(ComponentLookup);
    public static bool TryGetterHelper(ReadOnlySpan<byte> code,ulong rva,uint imageSize,out ulong helper)
    {
        helper=0;
        if(code.Length!=Getter.Length||rva>imageSize||(ulong)Getter.Length>imageSize-rva)return false;
        for(int i=0;i<Getter.Length;i++)if((i<51||i>=55)&&code[i]!=Getter[i])return false;
        long target=(long)rva+55+BitConverter.ToInt32(code.Slice(51,4));
        if(target<=0||(ulong)target>imageSize||(ulong)Helper.Length>imageSize-(ulong)target)return false;
        helper=(ulong)target;return true;
    }
}
